
        function generateSVGDataURI(title, category) {
            title = title || 'Sách giáo khoa';
            category = category || 'Tri thức';
            let bgColors = ['#1e3a8a', '#3b82f6'];
            
            if (category.includes('Văn') || category.includes('Văn học')) {
                bgColors = ['#831843', '#db2777'];
            } else if (category.includes('Toán') || category.includes('Khoa học')) {
                bgColors = ['#065f46', '#10b981'];
            } else if (category.includes('Sử') || category.includes('Địa')) {
                bgColors = ['#7c2d12', '#ea580c'];
            } else if (category.includes('Tiếng Anh') || category.includes('Ngoại ngữ')) {
                bgColors = ['#4c1d95', '#8b5cf6'];
            } else if (category.includes('Giáo dục') || category.includes('GDCD')) {
                bgColors = ['#1e1b4b', '#6366f1'];
            }

            const escapedTitle = String(title).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
            const escapedCat = String(category).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

            let titleLine1 = escapedTitle;
            let titleLine2 = '';
            if (escapedTitle.length > 18) {
                const words = escapedTitle.split(' ');
                const mid = Math.ceil(words.length / 2);
                titleLine1 = words.slice(0, mid).join(' ');
                titleLine2 = words.slice(mid).join(' ');
            }

            const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="400" viewBox="0 0 300 400"><defs><linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" style="stop-color:${bgColors[0]};stop-opacity:1" /><stop offset="100%" style="stop-color:${bgColors[1]};stop-opacity:1" /></linearGradient></defs><rect width="300" height="400" rx="12" fill="url(#grad)" /><rect x="15" y="15" width="270" height="370" rx="8" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="2" /><rect x="25" y="30" width="100" height="24" rx="12" fill="rgba(255,255,255,0.2)" /><text x="75" y="46" font-family="Arial, sans-serif" font-size="11" font-weight="bold" fill="#ffffff" text-anchor="middle">${escapedCat}</text><circle cx="150" cy="150" r="45" fill="rgba(255,255,255,0.15)" /><g fill="#ffffff" transform="translate(130, 130) scale(1.6)"><path d="M12 14l9-5-9-5-9 5 9 5z"/><path d="M12 14l6.16-3.422a12.083 12.083 0 01.665 6.479A11.952 11.952 0 0012 20.055a11.952 11.952 0 00-6.824-2.998 12.078 12.078 0 01.665-6.479L12 14z"/></g><text x="150" y="240" font-family="Arial, sans-serif" font-size="18" font-weight="bold" fill="#ffffff" text-anchor="middle">${titleLine1}</text>${titleLine2 ? `<text x="150" y="268" font-family="Arial, sans-serif" font-size="18" font-weight="bold" fill="#ffffff" text-anchor="middle">${titleLine2}</text>` : ''}<text x="150" y="340" font-family="Arial, sans-serif" font-size="12" fill="rgba(255,255,255,0.8)" text-anchor="middle">BOOKNEST • TRI THỨC</text></svg>`;

            return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
        }

        function handleImageError(imgEl, category) {
            if (!imgEl || imgEl.dataset.fallbackTried) return;
            imgEl.dataset.fallbackTried = "true";
            const title = imgEl.getAttribute('alt') || 'Sách';
            imgEl.src = generateSVGDataURI(title, category);
        }

