        function handleLogout() {
            currentUser = null;
            localStorage.removeItem('booknest_currentUser');
            updateUserHeaderUI();
            showToast('👋 Đã đăng xuất tài khoản thành công!');
        }

        function openLoginModal() {
            closeAllModals();
            const err = document.getElementById('loginErrorMsg');
            if (err) err.style.display = 'none';
            document.getElementById('loginModal').style.display = 'flex';
        }

        function openRegisterModal() {
            closeAllModals();
            const err = document.getElementById('registerErrorMsg');
            if (err) err.style.display = 'none';
            document.getElementById('registerModal').style.display = 'flex';
        }

        function handleLogin() {
            const userVal = document.getElementById('loginUsername').value.trim();
            const passVal = document.getElementById('loginPassword').value;
            const errDiv = document.getElementById('loginErrorMsg');

            if (!userVal) {
                errDiv.innerHTML = '❌ Vui lòng nhập số điện thoại hoặc tên tài khoản!';
                errDiv.style.display = 'block';
                return;
            }

            const foundAcc = registeredAccounts.find(a => a.phone === userVal || a.name?.toLowerCase() === userVal.toLowerCase());
            
            if (!foundAcc) {
                // Yêu cầu 2: Báo lỗi đỏ nổi bật nếu chưa có tài khoản
                errDiv.innerHTML = `❌ Tài khoản <strong>"${userVal}"</strong> chưa tồn tại trên hệ thống!<br>👉 Vui lòng <a href="#" onclick="openRegisterModal()" style="color:#2563eb; font-weight:800; text-decoration:underline;">Bấm vào đây để Đăng Ký Tài Khoản Mới</a>`;
                errDiv.style.display = 'block';
                return;
            }

            if (foundAcc.pass !== passVal) {
                errDiv.innerHTML = '❌ Sai mật khẩu! Vui lòng kiểm tra lại.';
                errDiv.style.display = 'block';
                return;
            }

            // Đăng nhập thành công
            currentUser = foundAcc;
            localStorage.setItem('booknest_currentUser', JSON.stringify(currentUser));
            updateUserHeaderUI();
            closeAllModals();
            showToast(`👋 Chào mừng khách hàng ${currentUser.name} đã đăng nhập!`);
        }

        function handleRegister() {
            const name = document.getElementById('regName').value.trim();
            const phone = document.getElementById('regPhone').value.trim();
            const pass = document.getElementById('regPassword').value;
            const errDiv = document.getElementById('registerErrorMsg');

            if (!name || !phone || !pass) {
                errDiv.innerText = '❌ Vui lòng điền đầy đủ các thông tin bắt buộc (*)!';
                errDiv.style.display = 'block';
                return;
            }

            const exist = registeredAccounts.find(a => a.phone === phone);
            if (exist) {
                errDiv.innerText = '❌ Số điện thoại này đã được đăng ký tài khoản! Vui lòng đăng nhập.';
                errDiv.style.display = 'block';
                return;
            }

            const newAcc = { name: name, phone: phone, pass: pass };
            registeredAccounts.push(newAcc);
            localStorage.setItem('booknest_accounts', JSON.stringify(registeredAccounts));

            // Tự động thêm vào mockUsers của Admin
            mockUsers.push({ id: mockUsers.length + 1, name: name, phone: phone, orders: 0, status: "Hoạt động" });

            // Tự động đăng nhập luôn
            currentUser = newAcc;
            localStorage.setItem('booknest_currentUser', JSON.stringify(currentUser));
            updateUserHeaderUI();
            closeAllModals();
            showToast(`🎉 Tạo tài khoản thành công! Chào mừng ${name}.`);
        }

        // -------------------------------------------------------------
        // THANH TOÁN (KHÔNG YÊU CẦU ĐĂNG NHẬP)
        // -------------------------------------------------------------

        let activeCouponDiscount = 0;
        let activeCouponCode = "";

        function openCheckoutModalFromCart() {
            if (cart.length === 0) {
                showToast('⚠️ Giỏ hàng của bạn đang trống!');
                return;
            }

            closeAllModals();

            // Auto-fill customer info if logged in
            document.getElementById('chkName').value = currentUser ? currentUser.name : '';
            document.getElementById('chkPhone').value = currentUser ? (currentUser.phone || '') : '';

            // Reset coupon state
            activeCouponDiscount = 0;
            activeCouponCode = "";
            document.getElementById('chkCouponInput').value = "";
            document.getElementById('chkCouponFeedback').innerText = "";

            updateCheckoutPriceSummary();
            document.getElementById('checkoutModal').style.display = 'flex';
        }

        function togglePaymentPreview(method) {
            const preview = document.getElementById('vietqrPreviewBox');
            if (preview) preview.style.display = (method === 'VietQR') ? 'block' : 'none';
        }

        function applyDiscountCoupon() {
            const codeInput = document.getElementById('chkCouponInput').value.trim().toUpperCase();
            const feedback = document.getElementById('chkCouponFeedback');
            const subtotal = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);

            if (!codeInput) {
                feedback.style.color = "#dc2626";
                feedback.innerText = "❌ Vui lòng nhập mã giảm giá!";
                return;
            }

            const coupon = mockCoupons.find(c => c.code === codeInput);
            if (!coupon) {
                feedback.style.color = "#dc2626";
                feedback.innerText = `❌ Mã "${codeInput}" không hợp lệ hoặc đã hết hạn!`;
                return;
            }

            activeCouponCode = coupon.code;
            if (coupon.discount.includes('%')) {
                const percent = parseInt(coupon.discount);
                activeCouponDiscount = Math.round(subtotal * (percent / 100));
            } else if (coupon.discount.includes('đ') || coupon.discount.includes('k')) {
                activeCouponDiscount = parseInt(coupon.discount.replace(/[^0-9]/g, '')) * (coupon.discount.includes('k') ? 1000 : 1);
            } else {
                activeCouponDiscount = 30000; // Freeship
            }

            feedback.style.color = "#16a34a";
            feedback.innerText = `✅ Đã áp dụng mã "${coupon.code}" (${coupon.desc}) - Giảm ${activeCouponDiscount.toLocaleString('vi-VN')}đ!`;
            updateCheckoutPriceSummary();
        }

        function updateCheckoutPriceSummary() {
            const subtotal = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);
            const shippingFee = subtotal > 0 ? 30000 : 0;
            const finalTotal = Math.max(0, subtotal + shippingFee - activeCouponDiscount);

            document.getElementById('chkSubTotal').innerText = subtotal.toLocaleString('vi-VN') + 'đ';
            document.getElementById('chkShippingFee').innerText = shippingFee.toLocaleString('vi-VN') + 'đ';
            document.getElementById('chkDiscountVal').innerText = '-' + activeCouponDiscount.toLocaleString('vi-VN') + 'đ';
            document.getElementById('chkFinalTotal').innerText = finalTotal.toLocaleString('vi-VN') + 'đ';
        }

        function handleCheckout() {
            const name = document.getElementById('chkName').value.trim();
            const phone = document.getElementById('chkPhone').value.trim();
            const addr = document.getElementById('chkAddress').value.trim();
            const paymentRadio = document.querySelector('input[name="chkPayment"]:checked');
            const paymentMethod = paymentRadio ? paymentRadio.value : "COD";

            if (!name || !phone || !addr) {
                showToast('⚠️ Vui lòng điền đầy đủ Họ tên, Số điện thoại và Địa chỉ giao hàng!');
                return;
            }

            const subtotal = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);
            const finalTotal = Math.max(0, subtotal + 30000 - activeCouponDiscount);

            const orderCode = "ORD-" + Math.floor(1000 + Math.random() * 9000);
            mockOrders.unshift({
                code: orderCode,
                name: name,
                phone: phone,
                payment: paymentMethod,
                total: finalTotal,
                status: "Chờ xử lý"
            });

            cart = [];
            saveCart();
            closeAllModals();
            showToast(`🎉 Đặt hàng thành công! Mã đơn: ${orderCode}. Cảm ơn khách hàng ${name}!`);
        }

        let isAdminLoggedIn = false;

        let mockOrders = [
            { code: "ORD-9821", name: "Nguyễn Văn An", phone: "0912345678", payment: "VietQR", total: 185000, status: "Đã hoàn thành" },
            { code: "ORD-9822", name: "Trần Thị Mai", phone: "0987654321", payment: "COD", total: 240000, status: "Đang giao" },
            { code: "ORD-9823", name: "Lê Hoàng Nam", phone: "0905123456", payment: "Ví MoMo", total: 155000, status: "Chờ xử lý" }
        ];

        let mockUsers = [
            { id: 1, name: "Nguyễn Văn An", phone: "0912345678", orders: 5, status: "Hoạt động" },
            { id: 2, name: "Trần Thị Mai", phone: "0987654321", orders: 3, status: "Hoạt động" },
            { id: 3, name: "Lê Hoàng Nam", phone: "0905123456", orders: 2, status: "Hoạt động" }
        ];

        let mockCoupons = [
            { code: "BOOKNEST10", discount: "10%", desc: "Giảm 10% cho mọi đơn hàng", status: "Đang hiệu lực" },
            { code: "HE2026", discount: "20.000đ", desc: "Giảm 20k đơn từ 150k", status: "Đang hiệu lực" },
            { code: "FREESHIP", discount: "Freeship", desc: "Miễn phí vận chuyển toàn quốc", status: "Đang hiệu lực" }
        ];

        function openAdminModal() {
            if (isAdminLoggedIn) {
                openAdminDashboard();
            } else {
                closeAllModals();
                document.getElementById('adminLoginModal').style.display = 'flex';
            }
        }

        function closeAllModals() {
            ['registerModal','loginModal','checkoutModal','adminLoginModal','adminDashboardModal','cartModal','bookDetailModal','coverLightboxModal'].forEach(id => {
                const el = document.getElementById(id); if (el) el.style.display = 'none';
            });
        }

        function handleAdminLogin() {
            const p = document.getElementById('adminPasswordInput').value;
            if(p === 'admin123') {
                isAdminLoggedIn = true;
                showToast('🔑 Đăng nhập Quản Trị thành công!');
                closeAllModals();
                openAdminDashboard();
            } else {
                showToast('⚠️ Sai mật khẩu Admin!');
            }
        }

        function openAdminDashboard() {
            closeAllModals();
            renderAdminBooksTable();
            renderAdminOrdersTable();
            renderAdminUsersTable();
            renderAdminCouponsTable();
            renderAdminCategoriesGrid();
            const el = document.getElementById('adminTotalBookCount');
            if (el) el.innerText = `${bookDatabase.length} Đầu sách`;
            document.getElementById('adminDashboardModal').style.display = 'flex';
        }

        function switchAdminTab(tabName) {
            document.querySelectorAll('.admin-section').forEach(sec => sec.style.display = 'none');
            document.querySelectorAll('.admin-tab-btn').forEach(btn => btn.classList.remove('active'));

            if (tabName === 'overview') {
                document.getElementById('adminSectionOverview').style.display = 'block';
                document.getElementById('tabAdminOverview').classList.add('active');
            } else if (tabName === 'books') {
                document.getElementById('adminSectionBooks').style.display = 'block';
                document.getElementById('tabAdminBooks').classList.add('active');
                renderAdminBooksTable();
            } else if (tabName === 'categories') {
                document.getElementById('adminSectionCategories').style.display = 'block';
                document.getElementById('tabAdminCategories').classList.add('active');
                renderAdminCategoriesGrid();
            } else if (tabName === 'orders') {
                document.getElementById('adminSectionOrders').style.display = 'block';
                document.getElementById('tabAdminOrders').classList.add('active');
                renderAdminOrdersTable();
            } else if (tabName === 'users') {
                document.getElementById('adminSectionUsers').style.display = 'block';
                document.getElementById('tabAdminUsers').classList.add('active');
                renderAdminUsersTable();
            } else if (tabName === 'coupons') {
                document.getElementById('adminSectionCoupons').style.display = 'block';
                document.getElementById('tabAdminCoupons').classList.add('active');
                renderAdminCouponsTable();
            }
        }

        function renderAdminBooksTable() {
            const tbody = document.getElementById('adminBooksTableBody');
            if (!tbody) return;
            tbody.innerHTML = bookDatabase.map(book => `
                <tr>
                    <td><strong>#${book.id}</strong></td>
                    <td><img src="${book.img}" alt="${book.name}" onerror="handleImageError(this, '${book.category}')" style="width: 36px; height: 48px; object-fit: cover; border-radius: 4px;"></td>
                    <td><strong>${book.name}</strong><br><small style="color:#64748b;">${book.author || 'Bộ GD&ĐT'}</small></td>
                    <td><span class="results-count-badge">${book.category}</span></td>
                    <td><strong style="color:#dc2626;">${book.price.toLocaleString('vi-VN')}đ</strong></td>
                    <td>
                        <input type="number" value="${book.stock || 50}" onchange="updateBookStock(${book.id}, this.value)" style="width: 60px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px; text-align: center; font-weight: 700;">
                    </td>
                    <td>
                        <button onclick="editBookFromAdmin(${book.id})" style="background:#e0f2fe; color:#0369a1; border:none; padding:4px 8px; border-radius:4px; font-weight:700; cursor:pointer;">✏️ Sửa</button>
                        <button onclick="deleteBookFromAdmin(${book.id})" style="background:#fee2e2; color:#b91c1c; border:none; padding:4px 8px; border-radius:4px; font-weight:700; cursor:pointer;">🗑️ Xóa</button>
                    </td>
                </tr>
            `).join('');
        }

        function updateBookStock(bookId, newStock) {
            const book = bookDatabase.find(b => b.id === bookId);
            if (book) {
                book.stock = parseInt(newStock) || 0;
                showToast(`📦 Đã cập nhật tồn kho "${book.name}": ${book.stock} cuốn`);
            }
        }

        function deleteBookFromAdmin(bookId) {
            const idx = bookDatabase.findIndex(b => b.id === bookId);
            if (idx !== -1) {
                const name = bookDatabase[idx].name;
                bookDatabase.splice(idx, 1);
                renderAdminBooksTable();
                executeSearch();
                const el = document.getElementById('adminTotalBookCount');
                if (el) el.innerText = `${bookDatabase.length} Đầu sách`;
                showToast(`🗑️ Đã xóa sách "${name}" khỏi kho!`);
            }
        }

        function editBookFromAdmin(bookId) {
            const book = bookDatabase.find(b => b.id === bookId);
            if (!book) return;
            const newName = prompt("Nhập tên sách mới:", book.name);
            if (newName && newName.trim() !== "") {
                book.name = newName.trim();
                const newPrice = prompt("Nhập giá mới (đ):", book.price);
                if (newPrice) book.price = parseInt(newPrice) || book.price;
                renderAdminBooksTable();
                executeSearch();
                showToast(`✏️ Đã cập nhật thông tin sách #${book.id}!`);
            }
        }

        function toggleAddBookForm() {
            const f = document.getElementById('adminAddBookForm');
            if (f) f.style.display = (f.style.display === 'none' || !f.style.display) ? 'block' : 'none';
        }

        function saveNewBookFromAdmin() {
            const nameInput = document.getElementById('newBookName');
            const priceInput = document.getElementById('newBookPrice');
            const name = nameInput.value.trim();
            const author = document.getElementById('newBookAuthor').value.trim() || "Bộ GD&ĐT";
            const category = document.getElementById('newBookCategory').value;
            const price = parseInt(priceInput.value) || 25000;
            const stock = parseInt(document.getElementById('newBookStock').value) || 50;
            let img = document.getElementById('newBookImg').value.trim();

            if (!name) {
                showToast('⚠️ Vui lòng nhập tên sách!');
                return;
            }

            if (!img) {
                img = getCoverUrl(name);
            }

            const newId = idCounter++;
            bookDatabase.unshift({
                id: newId,
                name: name,
                author: author,
                category: category,
                price: price,
                oldPrice: price + 10000,
                img: img,
                stock: stock,
                cssClass: 'cat-cap1'
            });

            nameInput.value = '';
            priceInput.value = '';
            toggleAddBookForm();
            renderAdminBooksTable();
            executeSearch();
            const el = document.getElementById('adminTotalBookCount');
            if (el) el.innerText = `${bookDatabase.length} Đầu sách`;
            showToast(`🎉 Đã thêm thành công sách mới: "${name}"!`);
        }

        function renderAdminOrdersTable() {
            const tbody = document.getElementById('adminOrdersTableBody');
            if (!tbody) return;
            tbody.innerHTML = mockOrders.map((o, idx) => `
                <tr>
                    <td><strong>${o.code}</strong></td>
                    <td><strong>${o.name}</strong></td>
                    <td>${o.phone}</td>
                    <td><span class="results-count-badge">${o.payment}</span></td>
                    <td><strong style="color:#dc2626;">${o.total.toLocaleString('vi-VN')}đ</strong></td>
                    <td>
                        <select onchange="updateOrderStatus(${idx}, this.value)" style="padding: 4px; border-radius: 6px; border: 1px solid #cbd5e1; font-weight: 700;">
                            <option value="Chờ xử lý" ${o.status==='Chờ xử lý'?'selected':''}>Chờ xử lý</option>
                            <option value="Đã xác nhận" ${o.status==='Đã xác nhận'?'selected':''}>Đã xác nhận</option>
                            <option value="Đang giao" ${o.status==='Đang giao'?'selected':''}>Đang giao</option>
                            <option value="Đã hoàn thành" ${o.status==='Đã hoàn thành'?'selected':''}>Đã hoàn thành</option>
                            <option value="Đã hủy" ${o.status==='Đã hủy'?'selected':''}>Đã hủy</option>
                        </select>
                    </td>
                </tr>
            `).join('');
        }

        function updateOrderStatus(idx, newStatus) {
            mockOrders[idx].status = newStatus;
            showToast(`📦 Đã cập nhật đơn hàng ${mockOrders[idx].code} sang "${newStatus}"`);
        }

        function renderAdminUsersTable() {
            const tbody = document.getElementById('adminUsersTableBody');
            if (!tbody) return;
            tbody.innerHTML = mockUsers.map(u => `
                <tr>
                    <td>#${u.id}</td>
                    <td><strong>${u.name}</strong></td>
                    <td>${u.phone}</td>
                    <td><strong>${u.orders} đơn</strong></td>
                    <td><span style="color:#16a34a; font-weight:700;">● ${u.status}</span></td>
                </tr>
            `).join('');
        }

        function renderAdminCouponsTable() {
            const tbody = document.getElementById('adminCouponsTableBody');
            if (!tbody) return;
            tbody.innerHTML = mockCoupons.map(c => `
                <tr>
                    <td><strong style="background:#fef3c7; color:#92400e; padding:2px 8px; border-radius:4px;">${c.code}</strong></td>
                    <td><strong style="color:#dc2626;">${c.discount}</strong></td>
                    <td>${c.desc}</td>
                    <td><span style="color:#16a34a; font-weight:700;">${c.status}</span></td>
                </tr>
            `).join('');
        }

        function addCouponFromAdmin() {
            const code = prompt("Nhập mã giảm giá mới (VD: KM50):");
            if (code && code.trim() !== "") {
                const discount = prompt("Nhập mức giảm (VD: 50.000đ hoặc 15%):", "10%");
                mockCoupons.push({ code: code.toUpperCase().trim(), discount: discount || "10%", desc: `Ưu đãi mã ${code}`, status: "Đang hiệu lực" });
                renderAdminCouponsTable();
                showToast(`🎟️ Đã tạo mã giảm giá mới: ${code.toUpperCase()}!`);
            }
        }

        function renderAdminCategoriesGrid() {
            const grid = document.getElementById('adminCategoriesGrid');
            if (!grid) return;
            const cats = [
                { name: "Cấp 1", count: 35, icon: "🎒" },
                { name: "Cấp 2", count: 32, icon: "📖" },
                { name: "Cấp 3", count: 24, icon: "🎓" },
                { name: "Đại học", count: 29, icon: "🏛️" },
                { name: "Văn học", count: 6, icon: "✍️" },
                { name: "Kinh tế", count: 4, icon: "📈" }
            ];
            grid.innerHTML = cats.map(c => `
                <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:16px; border-radius:12px; display:flex; align-items:center; gap:12px;">
                    <div style="font-size:28px;">${c.icon}</div>
                    <div>
                        <div style="font-size:15px; font-weight:800; color:#0f172a;">${c.name}</div>
                        <div style="font-size:12px; color:#64748b; font-weight:600;">${c.count} đầu sách</div>
                    </div>
                </div>
            `).join('');
        }

