        let currentDetailBook = null;

        function openBookDetailModal(bookId) {
            const book = bookDatabase.find(b => b.id === bookId); if (!book) return;
            currentDetailBook = book; 
            const sample = generateBookSamplePages(book);

            document.getElementById('detailBookImg').src = book.img;
            document.getElementById('detailBookTitle').innerText = book.name;
            document.getElementById('detailBookPrice').innerText = book.price.toLocaleString('vi-VN') + 'đ';
            document.getElementById('detailBookCategory').innerText = book.category;
            document.getElementById('detailBookCategory').className = 'cat-tag ' + (book.cssClass || 'cat-cap1');
            document.getElementById('detailBookDesc').innerHTML = sample.desc;
            document.getElementById('samplePageContent1').innerHTML = sample.p1;
            document.getElementById('samplePageContent2').innerHTML = sample.p2;

            switchSampleTab(1);

            document.getElementById('btnDetailAddCart').onclick = function() { addToCart(book.id); };
            document.getElementById('btnDetailBuyNow').onclick = function() { closeAllModals(); openCheckoutModalFromCart(); };

            renderRelatedBooks(book);
            document.getElementById('bookDetailModal').style.display = 'flex';
        }

        function switchSampleTab(tabNum) {
            const tab1 = document.getElementById('btnTab1');
            const tab2 = document.getElementById('btnTab2');
            const page1 = document.getElementById('samplePageContent1');
            const page2 = document.getElementById('samplePageContent2');

            if (tabNum === 1) {
                page1.style.display = 'block'; page2.style.display = 'none';
                tab1.style.background = '#ffffff'; tab1.style.color = 'var(--primary)'; tab1.style.borderBottom = '3px solid var(--primary)';
                tab2.style.background = 'transparent'; tab2.style.color = '#64748b'; tab2.style.borderBottom = 'none';
            } else {
                page1.style.display = 'none'; page2.style.display = 'block';
                tab2.style.background = '#ffffff'; tab2.style.color = 'var(--primary)'; tab2.style.borderBottom = '3px solid var(--primary)';
                tab1.style.background = 'transparent'; tab1.style.color = '#64748b'; tab1.style.borderBottom = 'none';
            }
        }

        function openCoverLightbox() {
            if (!currentDetailBook) return;
            document.getElementById('lightboxImg').src = currentDetailBook.img;
            document.getElementById('lightboxTitle').innerText = currentDetailBook.name;
            document.getElementById('coverLightboxModal').style.display = 'flex';
        }

        function closeCoverLightbox() {
            document.getElementById('coverLightboxModal').style.display = 'none';
        }

        function renderRelatedBooks(currentBook) {
            const grid = document.getElementById('relatedBooksGrid'); if (!grid) return;
            let related = bookDatabase.filter(b => b.category === currentBook.category && b.id !== currentBook.id);
            if (related.length < 4) {
                const others = bookDatabase.filter(b => b.id !== currentBook.id && !related.includes(b));
                related = related.concat(others);
            }
            const topRelated = related.slice(0, 4);
            grid.innerHTML = topRelated.map(b => `
                <div onclick="openBookDetailModal(${b.id})" style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px; text-align: center; cursor: pointer; transition: all 0.2s;">
                    <img src="${b.img}" alt="${b.name}" onerror="handleImageError(this, '${b.category}')" style="width: 100%; height: 110px; object-fit: cover; border-radius: 6px; margin-bottom: 8px;">
                    <div style="font-size: 11px; font-weight: 800; color: var(--primary); margin-bottom: 2px;">${b.category}</div>
                    <div style="font-size: 12px; font-weight: 700; color: var(--text-dark); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; height: 32px; line-height: 1.3;">${b.name}</div>
                    <div style="font-size: 12px; font-weight: 800; color: #dc2626; margin-top: 4px;">${b.price.toLocaleString('vi-VN')}đ</div>
                </div>`).join('');
        }

        window.addEventListener('DOMContentLoaded', () => {
            initDatabase();
            renderBestsellers();
            updateCartBadge();
            executeSearch();
            updateUserHeaderUI();
        });
    